css:
#ghl-custom-buttons-container { display:flex;flex-wrap:wrap;gap:8px;padding:10px 0;align-items:flex-start; }
.gcb-btn { display:inline-flex;align-items:center;gap:6px;padding:7px 14px;border:1px solid #d1d5db;border-radius:6px;background:#fff;font-size:13px;font-weight:500;cursor:pointer;color:#374151;position:relative;transition:all 0.15s;font-family:inherit; }
.gcb-btn:hover { background:#f9fafb;border-color:#9ca3af; }
.gcb-icon { width:14px;height:14px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0; }
.gcb-icon svg { width:14px;height:14px; }
.gcb-icon-dropdown svg { color:#3b82f6; }
.gcb-icon-link svg { color:#10b981; }
.gcb-icon-tag svg { color:#f59e0b; }
.gcb-arrow { font-size:10px;margin-left:2px; }
.gcb-dropdown { display:none;position:absolute;top:100%;left:0;background:#fff;border:1px solid #e2e8f0;border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,0.12);min-width:180px;z-index:10001;margin-top:4px;overflow:hidden; }
.gcb-dropdown.gcb-open { display:block; }
.gcb-dd-item { padding:10px 16px;font-size:13px;cursor:pointer;display:flex;align-items:center;gap:8px;transition:background 0.1s; }
.gcb-dd-item:hover { background:#f1f5f9; }
.gcb-settings-btn { display:inline-flex;align-items:center;gap:6px;padding:7px 12px;border:1px dashed #cbd5e1;border-radius:6px;background:#f8fafc;font-size:13px;cursor:pointer;color:#64748b;font-family:inherit;transition:all 0.15s; }
.gcb-settings-btn:hover { background:#e2e8f0; }
.gcb-panel-overlay { display:none;position:fixed;inset:0;background:rgba(0,0,0,0.3);z-index:10002; }
.gcb-panel-overlay.gcb-open { display:block; }
.gcb-panel { position:fixed;top:0;right:-360px;width:340px;height:100%;background:#fff;box-shadow:-4px 0 20px rgba(0,0,0,0.1);z-index:10003;transition:right 0.25s;overflow-y:auto;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif; }
.gcb-panel.gcb-open { right:0; }
.gcb-panel-header { padding:20px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between; }
.gcb-panel-header h3 { font-size:16px;font-weight:600;margin:0; }
.gcb-panel-close { background:none;border:none;font-size:22px;cursor:pointer;color:#94a3b8;padding:4px; }
.gcb-panel-body { padding:20px; }
.gcb-toggle-row { display:flex;align-items:center;justify-content:space-between;padding:12px 0;border-bottom:1px solid #f1f5f9; }
.gcb-toggle-label { font-size:14px;font-weight:500; }
.gcb-toggle-type { font-size:11px;color:#94a3b8;text-transform:uppercase; }
.gcb-switch { position:relative;width:44px;height:24px;flex-shrink:0; }
.gcb-switch input { opacity:0;width:0;height:0; }
.gcb-slider { position:absolute;cursor:pointer;inset:0;background:#cbd5e1;border-radius:24px;transition:0.2s; }
.gcb-slider:before { content:'';position:absolute;height:18px;width:18px;left:3px;bottom:3px;background:#fff;border-radius:50%;transition:0.2s; }
.gcb-switch input:checked + .gcb-slider { background:#3b82f6; }
.gcb-switch input:checked + .gcb-slider:before { transform:translateX(20px); }
.gcb-notif { position:fixed;bottom:24px;right:24px;padding:12px 20px;background:#1e293b;color:#fff;border-radius:8px;font-size:14px;box-shadow:0 8px 24px rgba(0,0,0,0.15);z-index:10010;opacity:0;transform:translateY(10px);transition:all 0.3s;font-family:inherit; }
.gcb-notif.gcb-show { opacity:1;transform:translateY(0); }
.gcb-notif-error { background:#dc2626; }
.gcb-form-overlay { position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:10020;display:flex;align-items:center;justify-content:center; }
.gcb-form-popup { background:#fff;border-radius:10px;width:460px;max-width:90vw;max-height:80vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,0.25);font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif; }
.gcb-form-header { padding:18px 24px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between; }
.gcb-form-header h3 { font-size:17px;font-weight:600;margin:0;color:#1e293b; }
.gcb-form-close { background:none;border:none;font-size:22px;cursor:pointer;color:#94a3b8;padding:4px;line-height:1; }
.gcb-form-close:hover { color:#475569; }
.gcb-form-body { padding:20px 24px; }
.gcb-form-group { margin-bottom:16px; }
.gcb-form-label { display:block;font-size:13px;font-weight:600;color:#475569;margin-bottom:6px; }
.gcb-form-input { width:100%;padding:9px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:14px;color:#1e293b;transition:border-color 0.15s;font-family:inherit;box-sizing:border-box; }
.gcb-form-input:focus { outline:none;border-color:#3b82f6;box-shadow:0 0 0 3px rgba(59,130,246,0.1); }
.gcb-form-error { font-size:12px;color:#dc2626;margin-top:4px;min-height:0; }
.gcb-form-footer { padding:14px 24px;border-top:1px solid #e2e8f0;display:flex;justify-content:flex-end;gap:10px; }
.gcb-form-btn { padding:8px 18px;border-radius:6px;font-size:14px;font-weight:500;cursor:pointer;border:none;transition:all 0.15s;font-family:inherit; }
.gcb-form-btn-cancel { background:#f1f5f9;color:#475569; }
.gcb-form-btn-cancel:hover { background:#e2e8f0; }
.gcb-form-btn-submit { background:#3b82f6;color:#fff; }
.gcb-form-btn-submit:hover { background:#2563eb; }
.gcb-form-btn-submit:disabled { opacity:0.6;cursor:not-allowed; }
